 VkPhysicalDeviceProperties props{};vkGetPhysicalDeviceProperties(physical,&props);uint32_t nq=0;vkGetPhysicalDeviceQueueFamilyProperties(physical,&nq,nullptr);std::vector<VkQueueFamilyProperties> qprops(nq);vkGetPhysicalDeviceQueueFamilyProperties(physical,&nq,qprops.data());uint32_t qf=UINT32_MAX;for(uint32_t i=0;i<nq;i++)if(qprops[i].queueFlags&VK_QUEUE_COMPUTE_BIT){qf=i;break;}if(qf==UINT32_MAX)throw std::runtime_error("no compute queue");
