 auto make_buffer=[&](size_t size){Buffer x;VkBufferCreateInfo bi{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};bi.size=size;bi.usage=VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;bi.sharingMode=VK_SHARING_MODE_EXCLUSIVE;check(vkCreateBuffer(device,&bi,nullptr,&x.b),"vkCreateBuffer");VkMemoryRequirements req{};vkGetBufferMemoryRequirements(device,x.b,&req);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=req.size;ai.memoryTypeIndex=memory_type(req.memoryTypeBits);check(vkAllocateMemory(device,&ai,nullptr,&x.m),"vkAllocateMemory");check(vkBindBufferMemory(device,x.b,x.m,0),"vkBindBufferMemory");check(vkMapMemory(device,x.m,0,size,0,&x.data),"vkMapMemory");return x;};
 VkDescriptorSetLayoutBinding bindings[3]{};for(uint32_t i=0;i<3;i++){bindings[i].binding=i;bindings[i].descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;bindings[i].descriptorCount=1;bindings[i].stageFlags=VK_SHADER_STAGE_COMPUTE_BIT;}VkDescriptorSetLayoutCreateInfo lci{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};lci.bindingCount=3;lci.pBindings=bindings;VkDescriptorSetLayout layout{};check(vkCreateDescriptorSetLayout(device,&lci,nullptr,&layout),"vkCreateDescriptorSetLayout");
